from kd_common import *
i=2
Z=lambda q,a:[('z',q),('b',a)]
def wrack(): return '<rect x="-80" y="-70" width="160" height="70" fill="#7a3b1f"/>'+g(-40,-30,1,gun(70))+g(30,-40,1,'<path d="M0 0 l40 -6" stroke="#9a9a9a" stroke-width="5"/><path d="M0 0 h-10" stroke="#5a3a1a" stroke-width="6"/>')+g(0,-10,.8,lotus('#e05050','#8e1f17'))
fw=foreword(i,['In the first days of September, when the paddy is planted and the rains ease, every Kodava family brings out its guns and knives, cleans them, garlands them and sets them before the lamp. This is <b>Kailpoḷd</b>, the festival of arms, and the second great festival of the Kodava year.',
 'This part explains the name, how the date is fixed, the house ritual, the food placed before the weapons, the village games at the mand, the old start of the hunting season, and what the festival means today.',
 'Part 1 '+L('/kodagu/kodavas/','introduced the Kodavas')+' and their martial tradition; Part 2 was '+L('/kodagu/puttari/','Puttari')+'. Next comes '+L('/kodagu/kaveri-sankramana/','Kāverī Saṅkramaṇa')+'.'],Z('Worshipping guns? Is that safe?','It is a puja of gratitude for protection, and the guns are farm guns. The shots fired after it are salutes.'))
gl=glance([('Name','Kailpoḷd, Kail Poldh or Kail Muhūrta'),('Meaning','Kail “arms”, poḷd “festival”'),('When','About the first week of September; 3 September outside Kodagu'),('Fixed by','The astrologer with the headman of each nāḍ'),('Ends','The hard work of paddy transplanting'),('Worshipped','Guns (kōvi), oḍi katti, pīcce katti, spears, farm tools'),('Offering','Kaḍambuṭṭ, pork curry and drink on a plantain leaf'),('At the mand','Coconut shooting, stone throwing, games'),('Old custom','Start of the hunting season'),('Other festivals',L('/kodagu/kaveri-sankramana/','Kāverī Saṅkramaṇa')+', '+L('/kodagu/puttari/','Puttari'))],
 S('Weapons on a rack before a lamp with flowers in the gun muzzles',g(280,210,1.6,wrack())+g(120,210,1.2,lamp())+g(440,210,1.2,kodava_man()),'#fff3cf',215),Z('Why September?','Transplanting is over. The family can rest, gather and give thanks.'),'Arms <b>before the lamp</b>.')
name=reading('name','THE NAME','Kail, poḷd and muhūrta',S('The words Kail Poḷd beside a gun and a knife',g(150,180,1.4,gun(90))+g(400,170,1.4,'<path d="M-40 0 l70 -10" stroke="#9a9a9a" stroke-width="8"/><path d="M-40 0 h-16" stroke="#5a3a1a" stroke-width="9"/>')+T(280,60,'kail + poḷd',20),'#fff3cf',215),
 ['<b>Kail.</b> In Kodava takk <b>kail</b> means arms or the armoury.','<b>Poḷd.</b> <b>Poḷd</b> means festival: Kailpoḷd, the festival of arms. Spellings vary: Kailpodh, Kail Poldh, Kail Podu.','<b>Kail Muhūrta.</b> An older name is <b>Kail Muhūrta</b>, the auspicious moment for the arms, because the puja is done at a fixed time.','<b>Not war.</b> The weapons are thanked for protecting the crops and the family: from wild boar, from elephants, from danger.','<b>In the calendar.</b> The festival falls in the Kodava month of <b>Chingyār</b> (see '+L('/kodagu/kodava-year/','Part 11')+').'],Z('Muhūrta for a gun?','For the puja. The exact minute is announced every year, like a wedding time.'),'A festival named <b>for the armoury</b>.')
date=reading('date','FIXING THE DAY','The astrologer and the nāḍ',S('Elders with an astrologer reading palm-leaf calendars',g(170,210,1.2,kodava_man())+g(230,210,1.2,kodava_man('#3a3a3a'))+g(380,210,1.2,person('#f4f1ea',seat=True))+g(450,190,.9,'<rect x="-30" y="-12" width="60" height="12" fill="#e9d6a0"/>'),'#fff3cf',215),
 ['<b>Old way.</b> The headman of the village, with the people of his <b>nāḍ</b>, consulted the astrologer for the auspicious day and hour.','<b>Today.</b> Temple astrologers and the families who hold the right announce the time, and newspapers print it: a puja “at 5.30 pm”, say.','<b>By region.</b> Different nāḍs in Kodagu may keep different days, often in late August or early September.','<b>Outside Kodagu.</b> Kodavas living in Bengaluru, Mysuru and abroad commonly keep <b>3 September</b>.','<b>Samājas.</b> Kodava Samājas hold community celebrations on or near the day.'],Z('So there is no single date?','A fixed 3 September for those away; local days in Kodagu, set the old way.'),'A day set <b>by elders and the stars</b>.')
work=reading('why','AFTER THE PLANTING','Why the arms rest',S('Paddy fields freshly planted, a plough laid aside',paddy(10,520,30).replace('<g','<g transform="translate(20 170)"',1)+g(140,200,1.2,'<path d="M-40 0 l60 -20 l20 6" stroke="#5a3a1a" stroke-width="5" fill="none"/>')+g(420,200,1.1,kodava_woman()),'#d8e8c8',215),
 ['<b>The hard months.</b> Ploughing and transplanting in the monsoon were the hardest work of the Kodava year.','<b>Rest.</b> Kailpoḷd marks the end of that labour: the fields are green and the men can turn back to the house.','<b>Arms put away.</b> Tradition says weapons were laid aside during the planting season and taken up again at Kailpoḷd. (Common account.)','<b>A family day.</b> Families scattered for work came home to the ainmane.','<b>The hunt.</b> In the old days the festival opened the hunting season (see below).'],Z('Rest from what?','From the mud and rain of the paddy. Then comes the gun.'),'When the paddy <b>is planted</b>.')
ritual=reading('ritual','THE HOUSE PUJA','Clean, oil, garland',S('A man oiling a gun in the central room; a lamp burns nearby',g(160,210,1.4,kodava_man())+g(260,190,1.3,gun(80))+g(420,210,1.6,hanging_lamp()),'#fff3cf',215),
 ['<b>Bring out.</b> On the morning of Kailpoḷd the family guns and blades are brought from where they rest, near the prayer corner, to the central room.','<b>Clean.</b> They are cleaned, burnished and oiled.','<b>Decorate.</b> They are smeared with sandal paste and garlanded; a <b>flower</b> (tok pū) is placed in the muzzle of each gun.','<b>Before the lamp.</b> They are laid before the sacred lamp, and the elder leads the prayer.','<b>Tools too.</b> Many families also honour farm tools beside the weapons.'],Z('A flower in the barrel?','The loveliest picture of the festival: a gun that holds a flower is at peace.'),'A flower <b>in the barrel</b>.')
offer=cards('offering','THE OFFERING','Food for the arms',fig_row('Plantain leaf with rice balls, pork curry and a cup',[('<path d="M-30 0 q30 -26 60 0z" fill="#2f8a3a"/>',1.4),('<circle r="12" fill="#f4f1ea"/><circle cx="18" r="12" fill="#f4f1ea"/>',1.2),('<path d="M-20 0 h40 l-6 -24 h-28z" fill="#5a3a1a"/>',1.2),('<path d="M-10 0 h20 l-3 -22 h-14z" fill="#d0a060"/>',1.2),(lamp(),1)],['leaf','kaḍambuṭṭ','pandi curry','drink','lamp'],gy=150),
 [('🍃','On a leaf','A plantain leaf is laid before the weapons.'),('⚪','Kaḍambuṭṭ','Steamed rice balls from the afternoon meal.'),('🍛','Pork curry','The festive pandi curry.'),('🥃','Drink','A share of the festive drink, by old custom.'),('🙏','Then the family','After the offering, the family eats the same meal.'),('🔥','Shots','Guns are fired outside as a salute.')],None,'The weapons <b>are served first</b>.',intro='As at every Kodava festival, what is offered is the family’s own food, not temple food.')
shoot=reading('shots','THE SALUTE','Shots across the valley',S('A man fires a gun into the sky from the courtyard; hills behind',hills(560,120,'#5a9a5a')+g(260,210,1.6,kodava_man())+'<path d="M276 120 l60 -70" stroke="#5a3a1a" stroke-width="5"/>'+g(345,40,1,flame()),'#d8e8f0',215),
 ['<b>After the puja.</b> When the ritual is done the elder steps out, and gunshots echo across the valley.','<b>A salute.</b> Shots are fired into the air: thanks and celebration, as at Puttari and weddings.','<b>Birthright.</b> Kodavas call gun ownership a birthright and say they never misuse it. (As reported in interviews.)','<b>The exemption.</b> Kodavas, and holders of ancestral land in Kodagu, have long been exempt from needing an arms licence, a right dating to British times. (As reported; challenged in court.)','<b>Children.</b> Many Kodavas remember helping a parent clean the gun as children.'],Z('Is it noisy?','Very. A whole valley sounds like a fort.'),'Thunder <b>without war</b>.')
mand=reading('games','AT THE MAND','Coconut shooting and stone throwing',S('Men aiming at a coconut hung from a tree; another throws a heavy stone',g(140,200,1.2,tree('#2f6a3a'))+'<path d="M140 100 v40" stroke="#5a3a1a" stroke-width="2"/><circle cx="140" cy="146" r="10" fill="#8a5a2a"/>'+g(300,210,1.3,kodava_man())+'<path d="M290 150 l-80 -10" stroke="#5a3a1a" stroke-width="4"/>'+g(460,210,1.3,kodava_man('#3a3a3a'))+'<circle cx="470" cy="130" r="12" fill="#8a8a8a"/>','#d8e8c8',215),
 ['<b>The village green.</b> In the afternoon villagers gather at their <b>mand</b> (see '+L('/kodagu/mand-and-dances/','Part 6')+').','<b>Coconut shooting.</b> A coconut is hung high and men shoot at it; hitting it is a matter of pride.','<b>Stone throwing.</b> Men compete throwing heavy stones, an old test of strength.','<b>Other games.</b> Races, tug-of-war and contests for children.','<b>Prizes and food.</b> Samājas give prizes; pork and rice dishes are served.'],Z('Can women shoot too?','Many do today, and win.'),'Aim, throw, <b>and eat</b>.')
hunt=reading('hunt','THE OLD HUNT','The start of the hunting season',S('Hunters with guns walking into the forest with a dog',g(140,210,1.6,tree('#2f6a3a'))+g(500,210,1.6,tree('#3a8a4a'))+g(260,210,1.2,kodava_man())+g(330,210,1.2,kodava_man('#3a3a3a'))+'<ellipse cx="400" cy="200" rx="18" ry="8" fill="#8a5a2a"/>','#d8e8c8',215),
 ['<b>Hunting season.</b> Kailpoḷd traditionally opened the hunting season, in Chingyār.','<b>Dēva bōḍi.</b> Old accounts tell of guns taken out a day before the festival for a ritual hunt, often for wild boar. (Kodava heritage accounts.)','<b>Protecting crops.</b> Hunting protected paddy from wild boar and deer.','<b>Today.</b> Hunting of wild animals is now banned under India’s wildlife law; the hunt survives only in memory and song.','<b>Coconut shooting</b> took its place as the test of the marksman.'],Z('So no hunting now?','No. The forest is protected. The coconut is the only target.'),'A hunt <b>now in memory</b>.')
story_=story('story','A KAILPOḶD MORNING','The boy and the flower',
 strip('Three panels: a grandfather oils a gun while a boy watches; the boy puts a flower in the muzzle; the family bows before the lamp and arms',
  [('<rect width="144" height="190" fill="#fff3cf"/>'+g(50,180,.9,kodava_man())+g(80,140,.6,gun(50))+g(115,180,.7,person('#1d4f8a')),'#fff3cf'),
   ('<rect width="144" height="190" fill="#fff3cf"/>'+g(70,130,1.2,gun(60))+g(104,112,.5,lotus('#e05050','#8e1f17'))+g(40,180,.7,person('#1d4f8a')),'#fff3cf'),
   ('<rect width="144" height="190" fill="#fff3cf"/>'+g(72,150,.7,wrack())+g(25,180,.6,person('#c0392b'))+g(120,180,.6,kodava_man()),'#fff3cf')],
  ['the oil cloth','the flower','the bow']),'A Kailpoḷd morning in an ancestral house (an illustrative story).',
 ['Rohan is eight. His grandfather lets him hold the oil cloth while the old gun is cleaned.','“Now the flower,” says Ajja. Rohan pushes it gently into the muzzle.','The family bows before the lamp. “The gun kept us safe all year. Today we keep it.”'])
today=reading('today','TODAY','Kailpoḷd now',S('A Samāja hall with a weapons display and families in traditional dress',g(280,200,1,'<rect x="-200" y="-90" width="400" height="90" fill="#e9d6c0"/><path d="M-210 -90 l210 -40 l210 40z" fill="#7a3b1f"/>')+g(200,200,1,kodava_man())+g(260,200,1,kodava_woman())+g(350,190,1,wrack()),'#fff3cf',215),
 ['<b>Homes first.</b> The core is still the puja in each ainmane and home.','<b>Samājas.</b> Kodava Samājas hold sports and cultural programmes.','<b>Exhibitions.</b> Some elders display antique weapons and utensils on the day.','<b>Everyone.</b> Kodavas and other communities of Kodagu honour arms and farm tools.','<b>Dress.</b> It is a day to wear the kupya and the Kodava sari.'],Z('Has it changed much?','The hunt has gone; the puja, the flower and the family meal are the same.'),'Old puja, <b>new halls</b>.')
endp=end(i,['<b>Name.</b> Kailpoḷd: kail “arms”, poḷd “festival”.','<b>When.</b> Early September, after transplanting; 3 September away from Kodagu.','<b>Ritual.</b> Weapons cleaned, garlanded, a flower in each muzzle, set before the lamp, offered food.','<b>Then.</b> Shots fired, games at the mand, the old hunt.'],'Part 4 is Kāverī Saṅkramaṇa.','The flower in the barrel')
src=sources([('Festival:','Coorg Tourism Info (C. A. Monappa) on Keil Muhurtha: astrologer, cleaning, tok pū in muzzle, kaḍambuṭṭ and pork on leaf; Scroll.in on the end of transplanting, shots and interviews; Deccan Herald (mands, stone throwing; Kail Poldh); Kodagu Express (Nalnad timing; 3 September outside Kodagu); Swarajya (3 September, kōvi puja); Kodava heritage site (Kailpodh nammera padathi).'),('Law:','The Quint on the arms-licence exemption.')],'“weapons laid aside during planting” is a common account; the dēva bōḍi ritual hunt follows a community heritage site.','Kodava terms romanised simply; spellings vary.')
finish(i,'PART 3 OF 12 · ARMS · LAMP · MAND',covart('Guns and knives garlanded before a lamp, a flower in a gun muzzle',g(220,180,1.5,wrack())+g(80,180,1,lamp())+g(370,180,1,kodava_man())),'The festival of arms',
 '<b>Kailpoḷd</b>, the Kodava festival of arms: the guns and knives cleaned, garlanded and set before the lamp with a <b>flower in each muzzle</b>, then shots and games at the mand.',
 'Kailpoḷd (Kailpodh) explained and illustrated: meaning, how the date is fixed, the weapons puja with flowers in gun muzzles, food offering, gun salutes, coconut shooting at the mand, the old hunting season and the festival today.',
 [fw,gl,name,date,work,ritual,offer,shoot,mand,hunt,story_,today,endp,src])
